/* Chicago Bulls DNA — united center night, bulls red on black */
.theme-chicago-bulls {
  --bg: oklch(0.147 0.003 17.6);
  --surface: oklch(0.192 0.007 17.7);
  --surface-2: oklch(0.230 0.011 18.0);
  --fg: oklch(1.000 0 0);
  --fg-muted: oklch(0.739 0.014 17.5);
  --accent: oklch(0.545 0.211 17.0);
  --accent-fg: oklch(1.000 0 0);
  --accent-2: oklch(1.000 0 0);
  --line: oklch(1 0 0 / 14%);
  --success: oklch(0.615 0.143 147.4);
  --warning: oklch(0.788 0.151 74.9);
  --danger: oklch(0.615 0.190 27.8);
  --radius: 0.375rem;
  --radius-sm: 0.25rem;
  --radius-lg: 0.5rem;
  --radius-pill: 9999px;
  --shadow-1: 0 2px 6px oklch(0 0 0 / 45%);
  --shadow-2: 0 8px 24px oklch(0 0 0 / 55%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 65%);
  --glow: 0 0 0 1px color-mix(in oklab, var(--accent) 45%, transparent);
  --border-width: 1px;
  --blur-amount: 0px;
  --font-display: "Big Shoulders", sans-serif;
  --font-body: "Inter", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --tracking-display: 0.01em;
  --label-transform: uppercase;
  --label-tracking: 0.1em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-chicago-bulls h1,
.theme-chicago-bulls h2,
.theme-chicago-bulls h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-chicago-bulls { --font-ui: var(--font-display); }
.theme-chicago-bulls h1, .theme-chicago-bulls h2 { text-transform: uppercase; font-weight: 800; }
.theme-chicago-bulls button { text-transform: uppercase; letter-spacing: 0.08em; font-weight: 700; }

.theme-chicago-bulls { background-image: radial-gradient(ellipse at 50% -10%, oklch(0.4 0.15 15 / 30%), transparent 55%); }
.theme-chicago-bulls h1 { color: var(--accent); }
.theme-chicago-bulls h1::after { content: ""; display: block; height: 4px; width: 6rem; margin-top: 0.6rem; background: #ffffff; }

/* depth */
.theme-chicago-bulls ::selection { background: var(--accent); color: var(--accent-fg); }
.theme-chicago-bulls a { color: oklch(0.72 0.17 18); text-decoration-color: color-mix(in oklab, var(--accent) 55%, transparent); text-underline-offset: 3px; }
.theme-chicago-bulls a:hover { color: #ffffff; text-decoration-color: var(--accent); text-decoration-thickness: 3px; }
.theme-chicago-bulls thead th { font-family: var(--font-display); text-transform: uppercase; letter-spacing: 0.1em; font-size: 0.8em; color: var(--fg-muted); background: oklch(0.165 0.006 18); border-bottom: 2px solid var(--accent); }
.theme-chicago-bulls td { border-bottom: 1px solid var(--line); }
.theme-chicago-bulls tbody tr:hover { background: oklch(0.545 0.211 17 / 9%); box-shadow: inset 3px 0 0 var(--accent); }
.theme-chicago-bulls input, .theme-chicago-bulls select, .theme-chicago-bulls textarea { background: oklch(0.128 0.004 18); border: 1px solid var(--line); caret-color: var(--accent); }
.theme-chicago-bulls input:focus-visible, .theme-chicago-bulls select:focus-visible, .theme-chicago-bulls textarea:focus-visible { outline: none; border-color: var(--accent); box-shadow: 0 0 0 3px oklch(0.545 0.211 17 / 30%); }
.theme-chicago-bulls kbd { font-family: var(--font-display); font-weight: 700; background: oklch(0.10 0.003 18); color: #ffffff; border: 1px solid var(--accent); border-bottom-width: 3px; border-radius: var(--radius-sm); padding: 0.1em 0.45em; }
.theme-chicago-bulls ::-webkit-scrollbar { width: 10px; height: 10px; }
.theme-chicago-bulls ::-webkit-scrollbar-track { background: oklch(0.128 0.004 18); }
.theme-chicago-bulls ::-webkit-scrollbar-thumb { background: oklch(0.42 0.15 18); border: 2px solid oklch(0.128 0.004 18); border-radius: 999px; }
.theme-chicago-bulls ::-webkit-scrollbar-thumb:hover { background: var(--accent); }
.theme-chicago-bulls .label-caps { color: oklch(0.68 0.19 18); font-weight: 700; }
.theme-chicago-bulls .themed-border { border-color: var(--accent); box-shadow: inset 0 0 0 1px oklch(1 0 0 / 7%); }
/* physical: the charge — buttons slam down like a drive to the rim */
.theme-chicago-bulls button:hover { box-shadow: 0 4px 0 oklch(0.35 0.13 18), var(--shadow-1); transform: translateY(-2px); }
.theme-chicago-bulls button:active { transform: translateY(1px); box-shadow: inset 0 2px 6px oklch(0 0 0 / 55%); }

/* alt mode: away kit (2026-27 real kit / NBA Association Edition) */
.theme-chicago-bulls.alt-mode {
  --bg: oklch(0.985 0 0);
  --surface: oklch(1.000 0 0);
  --surface-2: oklch(0.953 0.003 286.3);
  --fg: oklch(0.206 0.006 285.9);
  --fg-muted: oklch(0.478 0.016 285.8);
  --accent: oklch(0.545 0.211 17.0);
  --accent-fg: oklch(1.000 0 0);
  --accent-2: oklch(0.000 0 0);
  --line: oklch(0.914 0.005 286.3);
  --shadow-1: 0 1px 2px oklch(0 0 0 / 8%);
  --shadow-2: 0 6px 20px -8px oklch(0 0 0 / 15%);
  --shadow-3: 0 20px 50px -16px oklch(0 0 0 / 20%);
  background-image: none;
}
.theme-chicago-bulls.alt-mode h1 { background: none; -webkit-background-clip: initial; background-clip: initial; color: #ce1141; -webkit-text-stroke: 0; }
.theme-chicago-bulls.alt-mode input, .theme-chicago-bulls.alt-mode select, .theme-chicago-bulls.alt-mode textarea { background: #ffffff; border-color: var(--line); color: var(--fg); }
.theme-chicago-bulls.alt-mode thead th { background: oklch(0.165 0.006 18); color: oklch(0.88 0.005 18); }
.theme-chicago-bulls.alt-mode ::-webkit-scrollbar-track { background: oklch(0.95 0 0); }
.theme-chicago-bulls.alt-mode ::-webkit-scrollbar-thumb { border-color: oklch(0.95 0 0); }
.theme-chicago-bulls.alt-mode .label-caps { color: oklch(0.5 0.19 18); }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);

  /* Full app surface: sidebar, charts, app-level font + shadow + tracking vars.
     These are what real products (shadcn full kit, RootCX-style UI kits) consume —
     without them a retrofit looks half-themed. */
  --sidebar: var(--surface-2);
  --sidebar-foreground: var(--fg);
  --sidebar-primary: var(--accent);
  --sidebar-primary-foreground: var(--accent-fg);
  --sidebar-accent: color-mix(in oklab, var(--accent) 12%, var(--surface-2));
  --sidebar-accent-foreground: var(--fg);
  --sidebar-border: var(--line);
  --sidebar-ring: var(--accent);

  --chart-1: var(--accent);
  --chart-2: var(--accent-2);
  --chart-3: var(--success);
  --chart-4: var(--warning);
  --chart-5: var(--danger);

  --font-sans: var(--font-body);
  --font-heading: var(--font-app, var(--font-display));
  --font-serif: var(--font-display);

  --shadow-2xs: var(--shadow-1);
  --shadow-xs: var(--shadow-1);
  --shadow-sm: var(--shadow-1);
  --shadow: var(--shadow-2);
  --shadow-md: var(--shadow-2);
  --shadow-lg: var(--shadow-3);
  --shadow-xl: var(--shadow-3);
  --shadow-2xl: var(--shadow-3);

  --tracking-normal: 0em;
}

/* Base experience: make the theme own the canvas and native elements even in
   apps that never adopted semantic classes. Scoped to the theme wrapper. */
[class*="theme-"] {
  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}
[class*="theme-"] :is(h1, h2, h3, h4) { font-family: var(--font-display); }
[class*="theme-"] :is(code, pre, kbd, samp) { font-family: var(--font-mono); }
[class*="theme-"] ::selection { background: color-mix(in oklab, var(--accent) 30%, transparent); }

/* OPT-IN HARD MODE — add "sf-enforce" beside the theme class when the host app
   bakes font/shadow/radius literals into its compiled utilities (a var bridge
   cannot beat a literal). Targeted !important, fonts and surfaces only. */
[class*="theme-"].sf-enforce { font-family: var(--font-body) !important; }
[class*="theme-"].sf-enforce :is(h1, h2, h3, h4, [class*="font-heading"]) {
  font-family: var(--font-app, var(--font-display)) !important;
  letter-spacing: var(--tracking-display) !important;
}
/* Data stays data: metrics/KPIs keep the body face with aligned lining figures.
   The display face is for headlines ONLY — never on numbers. Opt specific
   elements INTO the display face with data-sf="display". */
[class*="theme-"] :is([class*="text-2xl"], [class*="text-3xl"], [class*="text-4xl"], [class*="text-5xl"]) {
  font-variant-numeric: lining-nums tabular-nums;
}
[class*="theme-"].sf-enforce [data-sf="display"] {
  font-family: var(--font-display) !important;
  letter-spacing: var(--tracking-display) !important;
}
[class*="theme-"] :is(.sf-num, [data-sf="num"]) {
  font-family: var(--font-body) !important;
  font-variant-numeric: lining-nums tabular-nums;
}
[class*="theme-"].sf-enforce :is(button, [role="button"]) { font-family: var(--font-ui, var(--font-body)) !important; }
[class*="theme-"].sf-enforce :is(code, pre, kbd) { font-family: var(--font-mono) !important; }
[class*="theme-"].sf-enforce :is(.bg-card, [class*="card"]) {
  box-shadow: var(--shadow-2) !important;
  border-radius: var(--radius-lg) !important;
  border: var(--border-width) solid var(--line) !important;
}
[class*="theme-"].sf-enforce :is([class*="shadow-sm"], [class*="shadow-md"]) { box-shadow: var(--shadow-1) !important; }
[class*="theme-"].sf-enforce :is([class*="shadow-lg"], [class*="shadow-xl"]) { box-shadow: var(--shadow-3) !important; }
